<?php
require __DIR__.'/app.php';
$error='';
if($_SERVER['REQUEST_METHOD']==='POST') {
 check_csrf();
 $name=trim($_POST['name']??''); $body=trim($_POST['body']??''); $rating=filter_var($_POST['rating']??'',FILTER_VALIDATE_INT);
 if(!$name || mb_strlen($name)>100 || mb_strlen($body)<10 || mb_strlen($body)>2000 || $rating<1 || $rating>5) $error='Enter your name, a rating, and a review between 10 and 2,000 characters.';
 elseif(limited('review',60)) $error='Please wait a minute before submitting another review.';
 else { $q=db()->prepare('INSERT INTO reviews(name,rating,body) VALUES(?,?,?)'); $q->execute([$name,$rating,$body]); flash('Thank you! Your review will appear after our team approves it.'); redirect('reviews.php'); }
}
$reviews=db()->query('SELECT * FROM reviews WHERE approved=1 ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Traveller reviews | Travenzo Travels</title><link rel="stylesheet" href="assets/enhancements.css"><link rel="icon" type="image/jpeg" href="assets/travenzo-logo.jpeg"></head><body class="portal public-reviews"><header class="portal-header"><a href="index.php" class="brand"><img class="portal-logo" src="assets/travenzo-logo.jpeg" alt="Travenzo Travels Sri Lanka" width="76" height="76"><span>Traveller reviews</span></a><a href="index.php#tour-plan">Explore our tours</a></header><main class="portal-main"><div class="page-heading"><p>Memories from Sri Lanka</p><h1>Every journey has a story.</h1><p>Share the places, people and moments that stayed with you.</p></div><?php if($message=take_flash()): ?><div class="notice" role="status"><?= e($message) ?></div><?php endif ?><div class="reviews-layout"><section><h2>Traveller reviews</h2><div class="review-grid"><?php foreach($reviews as $r): ?><article class="review-card"><div class="stars" aria-label="<?= (int)$r['rating'] ?> out of 5 stars"><?= str_repeat('★',(int)$r['rating']) ?></div><blockquote><?= nl2br(e($r['body'])) ?></blockquote><strong><?= e($r['name']) ?></strong><p><?= e(date('F Y',strtotime($r['created']))) ?></p></article><?php endforeach ?><?php if(!$reviews): ?><div class="empty-state"><h3>Your story could be the first.</h3><p>Reviews from our travellers will appear here once approved.</p></div><?php endif ?></div></section><section class="editor-panel"><h2>Share your experience</h2><p>Reviews are checked before publication.</p><?php if($error): ?><p class="notice error" role="alert"><?= e($error) ?></p><?php endif ?><form method="post"><?= csrf_field() ?><label>Your name<input name="name" required maxlength="100" value="<?= e($_POST['name']??'') ?>"></label><label>Your rating<select name="rating"><?php for($i=5;$i>=1;$i--): ?><option value="<?= $i ?>" <?= (int)($_POST['rating']??5)===$i?'selected':'' ?>><?= $i ?> stars</option><?php endfor ?></select></label><label>Your review<textarea name="body" required minlength="10" maxlength="2000" rows="7"><?= e($_POST['body']??'') ?></textarea></label><button class="button" type="submit">Submit review</button></form></section></div></main><footer class="portal-footer"><a href="index.php">Back to Travenzo Travels</a></footer></body></html>
